// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {keepMyEther} from "../src/keepMyEther.sol";

contract InvMutTest is Test {
    keepMyEther c;
    function setUp() public { c = new keepMyEther(); }
    function testFuzz_property(address actor, uint256 amount, uint256 seed) public {
        vm.assume(amount > 0);
        vm.assume(actor != address(0) && actor != address(c));
        Reverter reverter = new Reverter();
        address caller = reverter.actor();
        vm.deal(caller, amount);
        vm.prank(caller);
        (bool success,) = address(c).call{value: amount}("");
        require(success, "deposit failed");
        uint256 balanceBefore = c.balances(caller);
        assertEq(balanceBefore, amount, "balance should equal deposited amount");
        vm.prank(caller);
        try c.withdraw() {
            assertEq(c.balances(caller), 0, "balance must be zero after successful withdraw");
        } catch {
            assertEq(c.balances(caller), amount, "after revert, balance must remain unchanged (reference behavior)");
        }
        assertEq(c.balances(caller), amount, "balance must remain unchanged when external call fails");
    }
}

contract Reverter {
    fallback() external payable {
        revert("Revert on receive");
    }
    function actor() external view returns (address) {
        return address(this);
    }
}
